using System.Collections.Generic;public class Solution{Dictionary<int,List<string>>m=new();List<string>F(string s,int i,IList<string>w){if(m.ContainsKey(i))return m[i];var r=new List<string>();if(i==s.Length){r.Add("");return r;}foreach(var x in w)if(i+x.Length<=s.Length&&s.Substring(i,x.Length)==x)foreach(var t in F(s,i+x.Length,w))r.Add(x+(t==""?"":" "+t));m[i]=r;return r;}public IList<string> WordBreak(string s,IList<string>w)=>F(s,0,w);}
